class ParentListQuery(BaseModel):
    """Typed service contract."""
    limit: int = Field(20, ge=1, le={{max_limit}})
    offset: int = Field(0, ge=0)
    {{filter_field}}: bool | None = None

@router.get({{path}}, response_model=list[ParentRead])
def list_parent(db: Annotated[Session, Depends(session_provider)], query: Annotated[ParentListQuery, Query()]) -> list[Parent]:
    """List parent."""
    statement = select(Parent)
    if query.{{filter_field}} is not None:
        statement = statement.where(Parent.{{filter_field}} == query.{{filter_field}})
    return list(db.scalars(statement.order_by(Parent.id).limit(query.limit).offset(query.offset)))
